<template><div class="login"><ElCard class="box" shadow="never"><div class="mark">🐾</div><h1>宠物零食商城后台</h1><p>管理店铺资料、用户与商城订单</p><ElForm label-position="top" @submit.prevent="submit"><ElFormItem label="账号"><ElInput v-model="form.username" size="large"/></ElFormItem><ElFormItem label="密码"><ElInput v-model="form.password" type="password" show-password size="large" @keyup.enter="submit"/></ElFormItem><ElButton type="warning" size="large" class="btn" :loading="loading" @click="submit">登录管理后台</ElButton></ElForm></ElCard></div></template><script setup lang="ts">import{reactive,ref}from'vue';import{ElMessage}from'element-plus';import{useRouter}from'vue-router';import{api}from'../api';import{useSession}from'../stores/session';const form=reactive({username:'admin',password:''}),loading=ref(false),router=useRouter(),session=useSession();async function submit(){loading.value=true;try{const d:any=await api.login(form);session.save({token:d.accessToken,name:d.user.displayName});router.replace('/dashboard')}catch(e:any){ElMessage.error(e.message)}finally{loading.value=false}}</script><style scoped>.login{height:100%;display:grid;place-items:center;background:radial-gradient(circle at 20% 20%,#fff2cf,transparent 32%),linear-gradient(135deg,#fffaf0,#f3f5fa)}.box{width:430px;padding:24px 28px;border-radius:24px!important}.mark{font-size:46px}h1{margin:10px 0}p{color:#9299a9;margin:0 0 28px}.btn{width:100%;margin-top:8px}</style>
